test('window rolls over at the business-day boundary', () async {
  final w = ContingencyWindow(businessDays: 10);
  w.record(DateTime.now());
  w.record(DateTime.now());
  await Future.delayed(const Duration(milliseconds: 5));
  w.record(DateTime.now());
  expect(w.count, 3);
});

